
(function(){
  'use strict';
  const CONTACT_FALLBACK={whatsapp:'2348023154308',email:'info@apsgnigeria.org'};
  const BANK_FALLBACK={account_name:'APC Progressive Support Group',bank_name:'Eco Bank',account_number:'2930053955',minimum_donation:50000};
  const DONATION_BUNDLES=[50000,100000,250000,500000,1000000,5000000,10000000];
  const SPONSOR_BUNDLES=[50000,100000,250000,500000,1000000,5000000,10000000];
  const EVENT_TYPES=['Campaign road show','Inauguration','Political trip','Street walk','Fitness for members','Welfare outreach','Grassroots mobilisation','Voter education programme','Youth engagement summit','Women mobilisation programme','CWDI empowerment event','Community medical outreach','Town hall meeting','Stakeholder meeting','Media briefing','Door-to-door canvassing','PVC awareness campaign','Ward mobilisation','Local government rally','State chapter meeting','National executive meeting','Fundraising dinner','Training workshop','Volunteer orientation','Community sensitisation','Strategic leadership retreat','Campaign launch','Elder council engagement','Women leadership roundtable','Youth political bootcamp'];
  const VOLUNTEER_CATEGORIES=['Mobilisation exercise','Participate in upcoming event','Field canvassing','Grassroots outreach','Media support','Registration and records support','Protocol','Logistics','Welfare','Security support','Ushering','Social media support','Photography and video coverage','Content creation','Call center / phone outreach','Data entry','Ward coordination','Youth mobilisation','Women mobilisation','Event setup and cleanup','Transport coordination','Door-to-door campaign support','PVC awareness support','Polling unit coordination support'];
  const ITEM_CATEGORIES=['Premium campaign T-shirts','Branded caps','Volunteer vests / field jackets','Banners, stage backdrops and roll-up stands','Flyers, leaflets and voter education cards','Posters and approved wall visuals','Volunteer ID cards and lanyards','Flags, stickers and handbill packs','Political campaign vehicle','Office space','Fuel support','Sound system','Canopies and chairs','Refreshments','Media gadgets','Data and airtime support','Printing and branding support'];
  const IMPACT_AREAS=['APSG General Support','Campaign Support','Grassroots Mobilisation','Media and ICT Support','Youth Empowerment','Women / CWDI Support','Welfare and Community Outreach','Voter Education','Event Support','Special Project Support'];
  const DONATION_TYPES=['Cash Donation','Campaign Item Donation','Physical Item Pledge','Political Campaign Vehicle Support','Office Space Support','Media / ICT Support','Welfare Support','Custom Support'];
  const SPONSOR_PACKAGES=['Support Sponsor','Bronze Sponsor','Silver Sponsor','Gold Sponsor','Platinum Sponsor','Principal Sponsor','Legacy Sponsor','Strategic Partner','Official Event Sponsor','Community Impact Sponsor'];
  const state={settings:{bank:BANK_FALLBACK,contact:CONTACT_FALLBACK},events:[],currentDonation:null,currentSponsor:null,admin:{activeTab:'overview',data:{}}};
  const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
  function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
  function money(v){const n=Number(String(v||'').replace(/[^0-9.]/g,''));return n?new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(n):'₦0';}
  function num(v){return Number(String(v||'').replace(/[^0-9.]/g,''))||0;}
  function idDate(){const d=new Date();return String(d.getFullYear()).slice(-2)+String(d.getMonth()+1).padStart(2,'0');}
  function fallbackRefs(kind){const serial=String(Date.now()).slice(-6);const ym=idDate();if(kind==='sponsor')return{sponsorship_ref:`APSG-SPN-${ym}-${serial}`,payment_ref:`APSG-PAY-${ym}-${serial}`,receipt_ref:`APSG-RCP-${ym}-${serial}`};return{donation_ref:`APSG-DON-${ym}-${serial}`,payment_ref:`APSG-PAY-${ym}-${serial}`,receipt_ref:`APSG-RCP-${ym}-${serial}`,donor_ref:`APSG-DNR-${serial}`};}
  function uuid(){return (crypto&&crypto.randomUUID)?crypto.randomUUID():`apsg-${Date.now()}-${Math.random().toString(36).slice(2)}`;}
  function client(){return window.supabaseClient||window.apsgSupabase||window.APSG_SUPABASE||(window.APSG&&window.APSG.supabase)||window.supabase||null;}
  async function waitClient(){for(let i=0;i<35;i++){const c=client();if(c&&typeof c.from==='function')return c;await new Promise(r=>setTimeout(r,100));}return null;}
  function toast(msg,type='success'){let t=$('#apsgInvolveToast');if(!t){t=document.createElement('div');t.id='apsgInvolveToast';t.className='toast';document.body.appendChild(t);}t.innerHTML=`<i class="fa-solid ${type==='error'?'fa-triangle-exclamation':'fa-circle-check'}"></i> ${esc(msg)}`;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600);}
  function textOf(form){const fd=new FormData(form);const lines=[];for(const [k,v] of fd.entries()){if(v instanceof File)continue; if(String(v).trim())lines.push(`${k}: ${String(v).trim()}`);}return lines.join('\n');}
  function whatsapp(message){const number=(state.settings.contact.whatsapp||CONTACT_FALLBACK.whatsapp).replace(/\D/g,'');window.open(`https://wa.me/${number}?text=${encodeURIComponent(message)}`,'_blank','noopener');}
  function email(subject,body){const mail=state.settings.contact.email||CONTACT_FALLBACK.email;location.href=`mailto:${mail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;}
  function setOptions(sel,items,placeholder){const el=typeof sel==='string'?$(sel):sel;if(!el)return;el.innerHTML=(placeholder?`<option value="">${esc(placeholder)}</option>`:'')+items.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}
  function normalizeSettingRows(rows){const out={};(rows||[]).forEach(r=>{out[r.setting_key||r.key]=r.setting_value||r.value;});return out;}
  async function loadSettings(){
    try{
      if(window.APSGSettings){
        const settings=await window.APSGSettings.loadPublic();
        const bundle=window.APSGSettings.financeBundle(settings);
        state.settings.bank={...BANK_FALLBACK,...(bundle.bank||{})};
        state.settings.contact={...CONTACT_FALLBACK,...(bundle.contact||{})};
        state.settings.donation_bundles=bundle.donation_bundles||DONATION_BUNDLES;
        state.settings.sponsorship_bundles=bundle.sponsorship_bundles||SPONSOR_BUNDLES;
        state.settings.item_categories=bundle.item_categories||ITEM_CATEGORIES;
        state.settings.event_types=bundle.event_types||EVENT_TYPES;
        state.settings.volunteer_categories=bundle.volunteer_categories||VOLUNTEER_CATEGORIES;
        state.settings.rsvp_event_types=bundle.rsvp_event_types||EVENT_TYPES;
        state.settings.raw=settings;
        return state.settings;
      }
    }catch(e){console.info('Central settings fallback used:',e.message||e);}
    const c=await waitClient();if(!c)return state.settings;try{const {data,error}=await c.from('apsg_settings').select('*').eq('public_visible',true);if(error)throw error;const map=normalizeSettingRows(data);state.settings.bank={...BANK_FALLBACK,...(map.finance_settings||map.bank_settings||{})};state.settings.contact={...CONTACT_FALLBACK,...(map.contact_settings||{})};state.settings.donation_bundles=map.donation_bundles||DONATION_BUNDLES;state.settings.sponsorship_bundles=map.sponsorship_bundles||SPONSOR_BUNDLES;state.settings.item_categories=map.campaign_item_categories||ITEM_CATEGORIES;state.settings.event_types=map.event_types||EVENT_TYPES;state.settings.volunteer_categories=map.volunteer_categories||VOLUNTEER_CATEGORIES;}catch(e){console.info('Settings fallback used:',e.message||e);}return state.settings;}
  async function loadEvents(){const c=await waitClient();if(!c)return [];try{const today=new Date().toISOString().slice(0,10);const {data,error}=await c.from('apsg_events').select('*').eq('status','published').gte('event_date',today).order('event_date',{ascending:true});if(error)throw error;state.events=Array.isArray(data)?data:[];}catch(e){console.info('Event load skipped:',e.message||e);state.events=[];}return state.events;}
  function normalizePhone(value){return String(value||'').replace(/[\s\-()]/g,'').trim();}
  function phoneCandidates(value){const raw=normalizePhone(value);const digits=raw.replace(/\D/g,'');const list=[raw,digits];if(digits.startsWith('234'))list.push('0'+digits.slice(3),'+234'+digits.slice(3));if(digits.startsWith('0'))list.push('234'+digits.slice(1),'+234'+digits.slice(1));return [...new Set(list.filter(Boolean))];}
  function textKey(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
  function fullMemberName(member){return String(member?.full_name||`${member?.first_name||''} ${member?.last_name||''}`||'').trim()||'APSG Member';}
  function getFormField(form,name){return form?form.querySelector(`[name="${name}"]`):null;}
  function localValueFromForm(form){return ['lga','ward','state_chapter','state','local_government','lcda'].map(name=>getFormField(form,name)?.value).filter(Boolean).join(' ');}
  function setFieldIfBlank(form,name,value){const field=getFormField(form,name);if(field&&value&&!String(field.value||'').trim()){field.value=value;field.dispatchEvent(new Event('input',{bubbles:true}));field.dispatchEvent(new Event('change',{bubbles:true}));}}
  function applyMemberMatchToForm(row,box){const form=box?.closest('form')||null;if(!row||!form)return;const apsgId=row.reg_number||row.membership_id||'';setFieldIfBlank(form,'membership_id',apsgId);setFieldIfBlank(form,'full_name',row.full_name);setFieldIfBlank(form,'state_chapter',row.state);setFieldIfBlank(form,'state',row.state);setFieldIfBlank(form,'lga',row.lga||row.lcda);setFieldIfBlank(form,'ward',row.ward);const status=getFormField(form,'member_status');if(status){const apsgOption=[...status.options].find(opt=>/apsg member/i.test(opt.textContent||opt.value));if(apsgOption)status.value=apsgOption.value;}}
  async function lookupMemberByPhone(phone,target){const raw=normalizePhone(phone);const digits=raw.replace(/\D/g,'');const box=typeof target==='string'?$(target):target;if(box)box.innerHTML='';if(digits.length<8)return null;const c=await waitClient();if(!c)return null;const form=box?.closest('form')||null;const local=localValueFromForm(form);try{let response=await c.rpc('lookup_apsg_member_by_phone',{p_phone:raw,p_local:local||null});if(response.error&&/parameter|function|signature|p_local/i.test(response.error.message||'')){response=await c.rpc('lookup_apsg_member_by_phone',{p_phone:raw});}if(response.error)throw response.error;let rows=Array.isArray(response.data)?response.data:(response.data?[response.data]:[]);if(!rows.length&&phoneCandidates(raw).length){for(const candidate of phoneCandidates(raw)){const retry=await c.rpc('lookup_apsg_member_by_phone',{p_phone:candidate,p_local:local||null}).catch(error=>({error}));if(!retry.error&&Array.isArray(retry.data)&&retry.data.length){rows=retry.data;break;}}}const row=rows[0]||null;if(row&&box){applyMemberMatchToForm(row,box);box.dataset.matchedMemberId=row.id||'';box.dataset.matchedRegNumber=row.reg_number||'';box.innerHTML=`<div class="notice"><i class="fa-solid fa-id-card"></i><div><strong>APSG member matched:</strong> ${esc(fullMemberName(row))}<br><span>APSG ID: <strong>${esc(row.reg_number||row.membership_id||'Found')}</strong>${row.state?` • ${esc(row.state)}`:''}${row.lga?` • ${esc(row.lga)}`:''}${row.ward?` • ${esc(row.ward)}`:''}</span></div></div>`;}return row;}catch(e){console.info('APSG member lookup skipped:',e?.message||e);if(box)box.innerHTML='';return null;}}
  function bindMemberLookup(phoneSelector,targetSelector){const phone=typeof phoneSelector==='string'?$(phoneSelector):phoneSelector;if(!phone)return;const run=()=>lookupMemberByPhone(phone.value,targetSelector);phone.addEventListener('blur',run);phone.addEventListener('change',run);let timer=null;phone.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(phone.value.replace(/\D/g,'').length>=10)run();},650);});const form=phone.closest('form');['state_chapter','state','lga','ward','local_government','lcda'].forEach(name=>getFormField(form,name)?.addEventListener('blur',run));}

  async function getRefs(kind){const c=await waitClient();if(!c)return fallbackRefs(kind);try{const fn=kind==='sponsor'?'generate_apsg_sponsorship_refs':'generate_apsg_donation_refs';const {data,error}=await c.rpc(fn);if(error)throw error;return data||fallbackRefs(kind);}catch(e){return fallbackRefs(kind);}}
  function selectedAmount(prefix){const custom=num($(`#${prefix}CustomAmount`)?.value);const active=$$(`[data-${prefix}-amount].active`)[0];return custom||num(active?.dataset[`${prefix}Amount`]);}
  function bindAmountButtons(prefix){$$(`[data-${prefix}-amount]`).forEach(btn=>btn.addEventListener('click',()=>{$$(`[data-${prefix}-amount]`).forEach(b=>b.classList.remove('active'));btn.classList.add('active');const input=$(`#${prefix}CustomAmount`);if(input)input.value='';updatePaymentPreview(prefix);}));$(`#${prefix}CustomAmount`)?.addEventListener('input',()=>{$$(`[data-${prefix}-amount]`).forEach(b=>b.classList.remove('active'));updatePaymentPreview(prefix);});}
  function updatePaymentPreview(prefix){const amount=selectedAmount(prefix);const target=$(`#${prefix}AmountPreview`);if(target)target.textContent=money(amount);}
  function fillBankPanel(prefix,refs,amount,type,impact,name){const bank=state.settings.bank;const donor=String(name||'').trim();const narration=`APSG ${prefix==='donation'?'Donation':'Sponsorship'} - ${impact||type||'Support'} - ${donor||'Anonymous Donor'}`;const panel=$(`#${prefix}BankPanel`);if(!panel)return;panel.classList.add('show');panel.innerHTML=`<div class="section-head" style="margin-bottom:.5rem"><div><p class="section-kicker">Bank Transfer Step</p><h3 class="section-title" style="font-size:1.45rem">Transfer ${money(amount)}</h3></div><span class="badge pending">Awaiting Transfer</span></div><div class="bank-row"><span>Account Name</span><strong>${esc(bank.account_name)}</strong></div><div class="bank-row"><span>Bank Name</span><strong>${esc(bank.bank_name)}</strong></div><div class="bank-row"><span>Account No.</span><strong>${esc(bank.account_number)}</strong></div><div class="bank-row"><span>Amount</span><strong>${money(amount)}</strong></div><div class="bank-row"><span>Type</span><strong>${esc(type||'Support')}</strong></div><div class="bank-row"><span>Impact</span><strong>${esc(impact||'APSG General Support')}</strong></div><div class="bank-row"><span>Narration</span><strong>${esc(narration)}</strong></div><div class="bank-row"><span>Payment Ref</span><strong>${esc(refs.payment_ref)}</strong></div><div class="button-row" style="margin-top:.85rem"><button type="button" class="premium-btn gold" data-copy-bank="${prefix}"><i class="fa-solid fa-copy"></i>Copy Bank Details</button><button type="button" class="premium-btn green" data-show-confirm="${prefix}"><i class="fa-solid fa-check"></i>I Have Made The Transfer</button></div>`;
    panel.querySelector('[data-copy-bank]')?.addEventListener('click',()=>{navigator.clipboard?.writeText(`APSG Bank Transfer Details\nAccount Name: ${bank.account_name}\nBank: ${bank.bank_name}\nAccount Number: ${bank.account_number}\nAmount: ${money(amount)}\nNarration: ${narration}\nPayment Ref: ${refs.payment_ref}`);toast('Bank details copied');});
    panel.querySelector('[data-show-confirm]')?.addEventListener('click',()=>{const conf=$(`#${prefix}ConfirmWrap`);if(conf)conf.classList.remove('hidden');conf?.scrollIntoView({behavior:'smooth',block:'start'});});
  }
  async function uploadProof(file,ref){if(!file||!file.size)return null;const c=await waitClient();if(!c?.storage)return null;try{const safe=String(file.name||'proof').replace(/[^a-z0-9_.-]/gi,'-');const path=`payment-proofs/${ref}-${Date.now()}-${safe}`;const {data,error}=await c.storage.from('payment-proofs').upload(path,file,{upsert:false});if(error)throw error;const pub=c.storage.from('payment-proofs').getPublicUrl(data.path);return pub?.data?.publicUrl||data.path;}catch(e){console.info('Proof upload skipped:',e.message||e);return null;}}

  function publicReceiptData(type,base,payment={}){
    const isSponsor=type==='sponsor';
    const isAnon=/anonymous/i.test(String(base?.recognition_preference||''));
    const name=isSponsor?(base?.sponsor_name||base?.organization_name||'APSG Sponsor'):(isAnon?'Anonymous Donor':(base?.donor_name||'APSG Donor'));
    return {
      receipt_mode:isSponsor?'sponsorship':'pending_payment',
      receipt_status:'pending',
      source_type:isSponsor?'sponsorship':'donation',
      receipt_ref:base?.receipt_ref||fallbackRefs(isSponsor?'sponsor':'donation').receipt_ref,
      payment_ref:base?.payment_ref||fallbackRefs(isSponsor?'sponsor':'donation').payment_ref,
      source_ref:isSponsor?(base?.sponsorship_ref||''):(base?.donation_ref||''),
      supporter_ref:base?.donor_ref||base?.supporter_ref||'',
      recipient_name:name,
      phone:base?.phone||'',
      email:base?.email||'',
      state_chapter:base?.state_chapter||'',
      support_category:isSponsor?(base?.package_name||'Event Sponsorship'):(base?.donation_type||base?.impact_area||'APSG Support'),
      amount:base?.amount||0,
      transfer_sender_name:payment?.transfer_sender_name||'',
      receipt_note:'This is a pending payment confirmation receipt. Final receipt will be issued after APSG confirms the bank transfer.',
      issued_at:new Date().toISOString()
    };
  }
  function currentPublicReceipt(type){
    const base=type==='sponsor'?state.currentSponsor:state.currentDonation;
    const payment=type==='sponsor'?state.currentSponsorPayment:state.currentDonationPayment;
    if(!base)return null;
    return publicReceiptData(type,base,payment||{});
  }
  async function publicReceiptDoc(type){
    const receipt=currentPublicReceipt(type);
    if(!receipt){toast('Receipt is not ready yet. Submit transfer confirmation first.','error');return null;}
    return await pdfDocForReceipt(receipt);
  }
  function publicReceiptFilename(type){
    const r=currentPublicReceipt(type);
    return `${((r&&r.receipt_ref)||'apsg-pending-receipt').replace(/[^a-z0-9-]+/gi,'-')}.pdf`;
  }
  async function downloadPublicPendingReceipt(type){
    const doc=await publicReceiptDoc(type);
    if(!doc)return;
    doc.save(publicReceiptFilename(type));
    toast('Pending receipt PDF downloaded.');
  }
  async function viewPublicPendingReceipt(type){
    const r=currentPublicReceipt(type);
    if(!r){toast('Receipt is not ready yet. Submit transfer confirmation first.','error');return;}
    try{
      sessionStorage.setItem('apsg_receipt_view_payload',JSON.stringify(r));
      if(r.receipt_ref)sessionStorage.setItem('apsg_receipt_payload_'+r.receipt_ref,JSON.stringify(r));
    }catch(e){}
    const params=new URLSearchParams();
    if(r.receipt_ref)params.set('ref',r.receipt_ref);
    if(r.payment_ref)params.set('payment',r.payment_ref);
    params.set('source',type);
    window.open('/viewpdf.html?'+params.toString(),'_blank','noopener');
    toast('Opening full receipt PDF viewer.');
  }
  function fallbackWhatsAppAfterPdf(type){
    const r=currentPublicReceipt(type)||{};
    const number=(state.settings.contact.whatsapp||CONTACT_FALLBACK.whatsapp).replace(/\D/g,'');
    const label=type==='sponsor'?'sponsorship':'donation';
    const msg=[
      `APSG ${type==='sponsor'?'Sponsorship':'Donation'} Pending Verification`,
      `Receipt Ref: ${r.receipt_ref||''}`,
      `Payment Ref: ${r.payment_ref||''}`,
      `Record Ref: ${r.source_ref||''}`,
      `Name: ${r.recipient_name||''}`,
      `Amount: ${money(r.amount||0)}`,
      '',
      `I have generated and downloaded the pending ${label} PDF receipt. I will attach/send the PDF in WhatsApp for APSG verification.`
    ].join('\n');
    window.open(`https://wa.me/${number}?text=${encodeURIComponent(msg)}`,'_blank','noopener');
  }
  async function sharePublicPendingReceiptToWhatsApp(type,auto=false){
    const doc=await publicReceiptDoc(type);
    if(!doc)return;
    const r=currentPublicReceipt(type);
    const blob=doc.output('blob');
    const file=new File([blob],publicReceiptFilename(type),{type:'application/pdf'});
    const shareData={
      title:'APSG Pending Receipt PDF',
      text:`APSG pending receipt ${r.receipt_ref||''} for ${r.recipient_name||'supporter'}.`,
      files:[file]
    };
    try{
      if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share){
        await navigator.share(shareData);
        toast('PDF receipt shared. Choose WhatsApp if prompted by your device.');
        return true;
      }
      doc.save(publicReceiptFilename(type));
      fallbackWhatsAppAfterPdf(type);
      toast('PDF downloaded. Attach it in the WhatsApp chat that opened.');
      return false;
    }catch(error){
      if(!auto){toast('PDF share was cancelled or blocked. Downloading receipt instead.','error');}
      doc.save(publicReceiptFilename(type));
      fallbackWhatsAppAfterPdf(type);
      return false;
    }
  }
  async function initDonation(){const form=$('#donationForm');if(!form)return;await loadSettings();setOptions('#donationType',DONATION_TYPES,'Select donation type');setOptions('#impactArea',IMPACT_AREAS,'Select impact area');setOptions('#itemCategory',state.settings.item_categories||ITEM_CATEGORIES,'Select item/material category');const grid=$('#donationAmountGrid');if(grid)grid.innerHTML=(state.settings.donation_bundles||DONATION_BUNDLES).map(a=>`<button type="button" class="amount-btn" data-donation-amount="${a}">${money(a)}</button>`).join('');bindAmountButtons('donation');bindMemberLookup('#donorPhone','#donorMemberMatch');
    form.addEventListener('submit',async e=>{e.preventDefault();const c=await waitClient();const fd=new FormData(form);const refs=await getRefs('donation');const public_token=uuid();const amount=selectedAmount('donation');const payload={...refs,public_token,donation_type:fd.get('donation_type'),impact_area:fd.get('impact_area'),item_category:fd.get('item_category')||null,amount,custom_amount:amount,donor_name:fd.get('full_name'),phone:fd.get('phone'),email:fd.get('email'),member_status:fd.get('member_status'),membership_id:fd.get('membership_id'),state_chapter:fd.get('state_chapter'),lga:fd.get('lga'),ward:fd.get('ward'),recognition_preference:fd.get('recognition_preference'),donation_note:fd.get('donation_note'),status:'awaiting_transfer',payment_status:'awaiting_transfer'};try{if(c){const {error}=await c.from('apsg_donations').insert(payload);if(error)throw error;}state.currentDonation=payload;fillBankPanel('donation',refs,amount,payload.donation_type,payload.impact_area,payload.recognition_preference==='Anonymous donation'?'Anonymous Donor':payload.donor_name);toast('Donation reference generated. Complete the transfer step.');}catch(err){toast(err.message||'Could not save donation pledge','error');}});
    $('#donationConfirmForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!state.currentDonation)return toast('Generate donation reference first','error');const c=await waitClient();const fd=new FormData(e.currentTarget);const proof=await uploadProof(fd.get('payment_proof'),state.currentDonation.payment_ref);const payload={donation_ref:state.currentDonation.donation_ref,public_token:state.currentDonation.public_token,transfer_sender_name:fd.get('transfer_sender_name'),bank_transaction_ref:fd.get('bank_transaction_ref'),payment_note:fd.get('payment_note'),payment_proof_url:proof,status:'pending_verification',payment_status:'pending_verification'};try{if(c){let res=await c.rpc('public_confirm_apsg_donation_transfer',payload);if(res.error)throw res.error;}state.currentDonationPayment=payload;renderReceipt('donation',state.currentDonation,payload);toast('Pending payment receipt generated. Preparing PDF receipt for WhatsApp sharing.');await sharePublicPendingReceiptToWhatsApp('donation',true);}catch(err){toast(err.message||'Could not confirm transfer','error');}});
  }
  function renderReceipt(type,base,payment){const wrap=$(`#${type}Receipt`);if(!wrap)return;wrap.classList.remove('hidden');const label=type==='donation'?'Donation':'Sponsorship';wrap.innerHTML=`<div class="receipt-card public-pending-receipt"><div class="section-head" style="margin-bottom:.7rem"><div><p class="section-kicker">Pending PDF Receipt</p><h3><i class="fa-solid fa-file-pdf"></i> Pending Payment Confirmation Receipt</h3><p class="section-copy">Download or share this PDF receipt. Final receipt will be issued after APSG verifies the transfer.</p></div><span class="badge pending">Pending Verification</span></div><div class="receipt-box"><p><strong>Receipt Ref:</strong> ${esc(base.receipt_ref)}</p><p><strong>${label} Ref:</strong> ${esc(base.donation_ref||base.sponsorship_ref)}</p><p><strong>Payment Ref:</strong> ${esc(base.payment_ref)}</p><p><strong>Name:</strong> ${esc(base.donor_name||base.sponsor_name)}</p><p><strong>Amount:</strong> ${money(base.amount)}</p><p><strong>Status:</strong> Pending verification</p><p><strong>Important:</strong> This pending confirmation has been saved for APSG admin verification. Final PDF receipt will be issued from APSG after the transfer is confirmed.</p></div><div class="button-row" style="margin-top:1rem"><button type="button" class="premium-btn green" data-public-receipt-share="${type}"><i class="fa-brands fa-whatsapp"></i>Share PDF to WhatsApp</button><button type="button" class="premium-btn gold" data-public-receipt-download="${type}"><i class="fa-solid fa-download"></i>Download Pending Receipt PDF</button><button type="button" class="premium-btn white" data-public-receipt-view="${type}"><i class="fa-solid fa-eye"></i>View PDF</button></div></div>`;wrap.querySelector('[data-public-receipt-share]')?.addEventListener('click',()=>sharePublicPendingReceiptToWhatsApp(type,false));wrap.querySelector('[data-public-receipt-download]')?.addEventListener('click',()=>downloadPublicPendingReceipt(type));wrap.querySelector('[data-public-receipt-view]')?.addEventListener('click',()=>viewPublicPendingReceipt(type));}
  async function initSponsor(){const form=$('#sponsorForm');if(!form)return;await Promise.all([loadSettings(),loadEvents()]);setOptions('#sponsorPackage',SPONSOR_PACKAGES,'Select sponsorship package');const ev=$('#sponsorEvent');if(ev)ev.innerHTML='<option value="">Select published event</option>'+state.events.map(e=>`<option value="${esc(e.id)}" data-title="${esc(e.title)}">${esc(e.title)} • ${esc(e.event_date||'No date')}</option>`).join('');const grid=$('#sponsorAmountGrid');if(grid)grid.innerHTML=(state.settings.sponsorship_bundles||SPONSOR_BUNDLES).map(a=>`<button type="button" class="amount-btn" data-sponsor-amount="${a}">${money(a)}</button>`).join('');bindAmountButtons('sponsor');
    form.addEventListener('submit',async e=>{e.preventDefault();const c=await waitClient();const fd=new FormData(form);const refs=await getRefs('sponsor');const public_token=uuid();const amount=selectedAmount('sponsor');const eventEl=$('#sponsorEvent');const eventTitle=eventEl?.selectedOptions?.[0]?.dataset.title||fd.get('event_id')||'';const payload={...refs,public_token,event_id:fd.get('event_id')||null,event_title:eventTitle,sponsor_name:fd.get('sponsor_name'),organization_name:fd.get('organization_name'),phone:fd.get('phone'),email:fd.get('email'),state_chapter:fd.get('state_chapter'),package_name:fd.get('package_name'),amount,sponsor_note:fd.get('sponsor_note'),recognition_preference:fd.get('recognition_preference'),status:'awaiting_transfer',payment_status:'awaiting_transfer'};try{if(c){const {error}=await c.from('apsg_sponsorships').insert(payload);if(error)throw error;}state.currentSponsor=payload;fillBankPanel('sponsor',refs,amount,payload.package_name,eventTitle,payload.recognition_preference==='Anonymous sponsor'?'Anonymous Sponsor':payload.sponsor_name);toast('Sponsorship reference generated. Complete the transfer step.');}catch(err){toast(err.message||'Could not save sponsorship pledge','error');}});
    $('#sponsorConfirmForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!state.currentSponsor)return toast('Generate sponsorship reference first','error');const c=await waitClient();const fd=new FormData(e.currentTarget);const proof=await uploadProof(fd.get('payment_proof'),state.currentSponsor.payment_ref);const payload={sponsorship_ref:state.currentSponsor.sponsorship_ref,public_token:state.currentSponsor.public_token,transfer_sender_name:fd.get('transfer_sender_name'),bank_transaction_ref:fd.get('bank_transaction_ref'),payment_note:fd.get('payment_note'),payment_proof_url:proof,status:'pending_verification',payment_status:'pending_verification'};try{if(c){const res=await c.rpc('public_confirm_apsg_sponsorship_transfer',payload);if(res.error)throw res.error;}state.currentSponsorPayment=payload;renderReceipt('sponsor',state.currentSponsor,payload);toast('Pending sponsor receipt generated. Preparing PDF receipt for WhatsApp sharing.');await sharePublicPendingReceiptToWhatsApp('sponsor',true);}catch(err){toast(err.message||'Could not confirm transfer','error');}});
  }
  async function initVolunteer(){const form=$('#volunteerForm');if(!form)return;await Promise.all([loadSettings(),loadEvents()]);setOptions('#volunteerCategory',state.settings.volunteer_categories||VOLUNTEER_CATEGORIES,'Select volunteer category');const ev=$('#volunteerEvent');if(ev)ev.innerHTML='<option value="">Any upcoming APSG event</option>'+state.events.map(e=>`<option value="${esc(e.id)}" data-title="${esc(e.title)}">${esc(e.title)} • ${esc(e.event_date||'No date')}</option>`).join('');bindMemberLookup('#volunteerPhone','#volunteerMemberMatch');form.addEventListener('submit',async e=>{e.preventDefault();const c=await waitClient();const fd=new FormData(form);const evEl=$('#volunteerEvent');const payload={full_name:fd.get('full_name'),phone:fd.get('phone'),email:fd.get('email'),member_status:fd.get('member_status'),membership_id:fd.get('membership_id'),state_chapter:fd.get('state_chapter'),lga:fd.get('lga'),ward:fd.get('ward'),category:fd.get('category'),event_id:fd.get('event_id')||null,event_title:evEl?.selectedOptions?.[0]?.dataset.title||'',availability:fd.get('availability'),skills:fd.get('skills'),experience:fd.get('experience'),notes:fd.get('notes'),emergency_contact_name:fd.get('emergency_contact_name'),emergency_contact_phone:fd.get('emergency_contact_phone'),status:'submitted'};try{if(c){const {error}=await c.from('apsg_volunteers').insert(payload);if(error)throw error;}toast('Volunteer application submitted. APSG will review and contact you.');form.reset();}catch(err){toast(err.message||'Could not submit volunteer application','error');}});}
  async function initRsvp(){const form=$('#rsvpForm');if(!form)return;await loadEvents();const ev=$('#rsvpEvent');if(ev)ev.innerHTML='<option value="">Select published event</option>'+state.events.map(e=>`<option value="${esc(e.id)}" data-title="${esc(e.title)}">${esc(e.title)} • ${esc(e.event_date||'No date')}</option>`).join('');form.addEventListener('submit',async e=>{e.preventDefault();const c=await waitClient();const fd=new FormData(form);const evEl=$('#rsvpEvent');const payload={full_name:fd.get('full_name'),phone:fd.get('phone'),email:fd.get('email'),member_status:fd.get('member_status'),state_chapter:fd.get('state_chapter'),event_id:fd.get('event_id')||null,event_title:evEl?.selectedOptions?.[0]?.dataset.title||'',guest_count:num(fd.get('guest_count'))||1,attendance_note:fd.get('attendance_note'),status:'submitted'};try{if(c){const {error}=await c.from('apsg_rsvps').insert(payload);if(error)throw error;}toast('RSVP submitted. APSG protocol team will review your attendance.');form.reset();}catch(err){toast(err.message||'Could not submit RSVP','error');}});}
  function initGateway(){const el=$('#quickInterestForm');if(!el)return;el.addEventListener('submit',e=>{e.preventDefault();whatsapp('APSG Get Involved Interest\n\n'+textOf(el));toast('Opening WhatsApp confirmation');});$('#copyInterestBtn')?.addEventListener('click',()=>{navigator.clipboard?.writeText('APSG Get Involved Interest\n\n'+textOf(el));toast('Interest message copied');});}
  function publicInit(){initGateway();initDonation();initSponsor();initVolunteer();initRsvp();$$('[data-copy-text]').forEach(b=>b.addEventListener('click',()=>{navigator.clipboard?.writeText(b.dataset.copyText||'');toast('Copied');}));}
  // Admin
  async function checkAdmin(){const c=await waitClient();if(!c?.auth?.getSession){location.href='/admin/login.html?redirect='+encodeURIComponent(location.pathname);return null;}const {data}=await c.auth.getSession();const user=data?.session?.user;if(!user){location.href='/admin/login.html?redirect='+encodeURIComponent(location.pathname);return null;}let profile=null;try{let res=await c.from('admin_profiles').select('id,user_id,email,role,is_active,status').eq('id',user.id).maybeSingle();if(!res.data)res=await c.from('admin_profiles').select('id,user_id,email,role,is_active,status').eq('user_id',user.id).maybeSingle();if(!res.data&&user.email)res=await c.from('admin_profiles').select('id,user_id,email,role,is_active,status').ilike('email',user.email).maybeSingle();profile=res.data;}catch(e){}const role=String(profile?.role||'viewer').toLowerCase();const active=profile&&profile.is_active!==false&&String(profile.status||'active')!=='inactive';if(!active||!['admin','superadmin','editor'].includes(role)){toast('This dashboard requires active APSG admin/editor access.','error');}$('#adminRoleLabel')&&( $('#adminRoleLabel').textContent=role );$$('[data-role-level]').forEach(x=>x.classList.toggle('active',x.dataset.roleLevel===role));$$('[data-access]').forEach(link=>{const allowed=String(link.dataset.access||'').split(',').map(x=>x.trim());link.hidden=allowed.length&&!allowed.includes(role);});return {user,role};}
  async function adminFetch(table){const c=await waitClient();try{const {data,error}=await c.from(table).select('*').order('created_at',{ascending:false}).limit(1000);if(error)throw error;return Array.isArray(data)?data:[];}catch(e){console.info('Admin fetch failed',table,e.message||e);return [];}}
  async function loadAdminData(){const tables=['apsg_donations','apsg_sponsorships','apsg_volunteers','apsg_rsvps','apsg_events','apsg_payment_receipts'];const [donations,sponsorships,volunteers,rsvps,events,receipts]=await Promise.all(tables.map(adminFetch));state.admin.data={donations,sponsorships,volunteers,rsvps,events,receipts};renderOverview();renderAdminTables();}
  function stat(id,val){const el=document.querySelector(`[data-stat="${id}"]`);if(el)el.textContent=typeof val==='number'?val.toLocaleString():val;}
  function renderOverview(){const d=state.admin.data.donations||[],s=state.admin.data.sponsorships||[],v=state.admin.data.volunteers||[],r=state.admin.data.rsvps||[],e=state.admin.data.events||[];const today=new Date().toISOString().slice(0,10);stat('totalDonations',d.length);stat('confirmedDonations',d.filter(x=>x.status==='confirmed').length);stat('pendingDonations',d.filter(x=>['awaiting_transfer','pending_verification','pledged'].includes(x.status)).length);stat('donationValue',money(d.filter(x=>x.status==='confirmed').reduce((a,b)=>a+num(b.amount),0)));stat('itemPledges',d.filter(x=>String(x.donation_type||'').toLowerCase().includes('item')||String(x.donation_type||'').toLowerCase().includes('material')).length);stat('sponsorPledges',s.length);stat('confirmedSponsors',s.filter(x=>x.status==='confirmed').length);stat('sponsorValue',money(s.filter(x=>x.status==='confirmed').reduce((a,b)=>a+num(b.amount),0)));stat('volunteers',v.length);stat('approvedVolunteers',v.filter(x=>['approved','assigned','checked_in','completed'].includes(x.status)).length);stat('rsvps',r.length);stat('upcomingEvents',e.filter(x=>x.status==='published').length);stat('todaySubmissions',[...d,...s,...v,...r].filter(x=>String(x.created_at||'').slice(0,10)===today).length);stat('pendingVerification',[...d,...s].filter(x=>x.status==='pending_verification').length);stat('rejectedUnmatched',[...d,...s].filter(x=>['rejected','unmatched'].includes(x.status)).length);}
  function statusBadge(st){const s=String(st||'submitted').toLowerCase();let cls=s; if(['awaiting_transfer','pending_verification','pledged','submitted'].includes(s))cls='pending'; return `<span class="badge ${esc(cls)}">${esc(s.replace(/_/g,' '))}</span>`;}
  function reportLabel(kind){return {donations:'Donation Records',pledges:'Item Pledge Records',sponsorships:'Sponsorship Records',volunteers:'Volunteer Applications',rsvps:'RSVP Attendance Records',events:'Engagement Events',verification:'Payment Verification Queue',receipts:'Receipt Register'}[kind]||titleCaseText(kind||'records');}
  function rowActions(kind,id,status){const ref=`${kind}:${esc(id)}`;return `<div class="action-group"><button class="icon-btn" data-view-record="${ref}"><i class="fa-solid fa-eye"></i>View</button><button class="icon-btn green" data-action="${kind}:${esc(id)}:confirmed"><i class="fa-solid fa-check"></i>Verify</button><button class="icon-btn red" data-action="${kind}:${esc(id)}:rejected"><i class="fa-solid fa-xmark"></i>Reject</button><button class="icon-btn gold" data-preview-receipt="${ref}"><i class="fa-solid fa-eye"></i>Preview</button><button class="icon-btn" data-view-receipt="${ref}"><i class="fa-solid fa-file-pdf"></i>View PDF</button><button class="icon-btn green" data-download-receipt="${ref}"><i class="fa-solid fa-download"></i>Download PDF</button></div>`;}
  function reportMetrics(rows,kind){const total=rows.length;const pending=rows.filter(x=>['submitted','pledged','awaiting_transfer','pending_verification','pending'].includes(String(x.status||x.receipt_status||'').toLowerCase())).length;const confirmed=rows.filter(x=>['confirmed','final','approved','assigned','checked_in','completed','published'].includes(String(x.status||x.receipt_status||'').toLowerCase())).length;const value=rows.reduce((sum,x)=>sum+num(x.amount||x.sponsorship_target||0),0);const labels=kind==='volunteers'?['Applications','Pending','Approved+','Event-linked']:kind==='rsvps'?['RSVPs','Pending','Confirmed+','Guests']:kind==='events'?['Events','Draft/Pending','Published/Closed','Target Value']:kind==='receipts'?['Receipts','Pending','Final','Value']:['Records','Pending','Confirmed','Value'];const fourth=kind==='volunteers'?rows.filter(x=>x.event_id||x.event_title).length:kind==='rsvps'?rows.reduce((s,x)=>s+num(x.guest_count||1),0):money(value);return [[labels[0],fmt(total)],[labels[1],fmt(pending)],[labels[2],fmt(confirmed)],[labels[3],typeof fourth==='number'?fmt(fourth):fourth]];}
  function fmt(n){return Number(n||0).toLocaleString('en-NG');}
  function reportShell(kind,rows,headers,body,sub=''){const metrics=reportMetrics(rows,kind);return `<div class="premium-report-shell" data-report="${esc(kind)}"><div class="premium-report-head"><div><h3 class="premium-report-title">${esc(reportLabel(kind))}</h3><p class="premium-report-sub">${esc(sub||'Premium APSG administrative report with search, status actions and export-ready records.')}</p></div><input class="premium-report-search" type="search" placeholder="Search this report..." data-report-search="${esc(kind)}"></div><div class="premium-report-metrics">${metrics.map(([a,b])=>`<div class="premium-report-metric"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div><div class="premium-table-wrap"><table class="premium-admin-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div></div>`;}
  function noReport(kind){return `<div class="premium-report-shell"><div class="premium-report-head"><div><h3 class="premium-report-title">${esc(reportLabel(kind))}</h3><p class="premium-report-sub">No records found yet.</p></div></div><div class="notice"><i class="fa-solid fa-folder-open"></i><div>No ${esc(reportLabel(kind).toLowerCase())} available yet.</div></div></div>`;}
  function tableHTML(rows,kind){if(!rows.length)return noReport(kind);let headers=[],body='',sub='';if(kind==='donations'||kind==='pledges'){headers=['Reference','Donor','Support Type','Impact / Item','Amount','Status','Submitted','Actions'];sub=kind==='pledges'?'Campaign material and physical item pledge report.':'Donation report with payment verification and receipt actions.';body=rows.map(x=>`<tr><td><span class="cell-ref"><i class="fa-solid fa-fingerprint"></i>${esc(x.donation_ref||'No ref')}</span><span class="cell-sub">${esc(x.payment_ref||'')}</span></td><td><span class="cell-title">${esc(x.donor_name||'Unnamed donor')}</span><span class="cell-sub">${esc(x.phone||'No phone')} ${x.email?'• '+esc(x.email):''}</span></td><td><span class="cell-title">${esc(x.donation_type||'Donation')}</span><span class="cell-sub">${esc(x.member_status||'')}</span></td><td><span class="cell-title">${esc(x.impact_area||x.item_category||'APSG Support')}</span><span class="cell-sub">${esc(x.item_category||x.donation_note||'')}</span></td><td class="amount-cell">${money(x.amount)}</td><td>${statusBadge(x.status)}</td><td>${esc((x.created_at||'').slice(0,10))}</td><td>${rowActions('donations',x.id,x.status)}</td></tr>`).join('');}
    if(kind==='sponsorships'){headers=['Reference','Sponsor','Event / Package','Amount','Recognition','Status','Submitted','Actions'];sub='Event sponsorship report with premium package, payment and receipt actions.';body=rows.map(x=>`<tr><td><span class="cell-ref"><i class="fa-solid fa-award"></i>${esc(x.sponsorship_ref||'No ref')}</span><span class="cell-sub">${esc(x.payment_ref||'')}</span></td><td><span class="cell-title">${esc(x.sponsor_name||'Unnamed sponsor')}</span><span class="cell-sub">${esc(x.organization_name||'')} ${x.phone?'• '+esc(x.phone):''}</span></td><td><span class="cell-title">${esc(x.event_title||'No event')}</span><span class="cell-sub">${esc(x.package_name||'No package')}</span></td><td class="amount-cell">${money(x.amount)}</td><td>${esc(x.recognition_preference||'')}</td><td>${statusBadge(x.status)}</td><td>${esc((x.created_at||'').slice(0,10))}</td><td>${rowActions('sponsorships',x.id,x.status)}</td></tr>`).join('');}
    if(kind==='volunteers'){headers=['Volunteer','Category / Skills','Event','Location','Availability','Status','Submitted','Actions'];sub='World-class volunteer application report for assignment, check-in and mobilisation tracking.';body=rows.map(x=>`<tr><td><span class="cell-title">${esc(x.full_name||'Unnamed volunteer')}</span><span class="cell-sub">${esc(x.phone||'No phone')} ${x.email?'• '+esc(x.email):''}</span></td><td><span class="cell-title">${esc(x.category||'No category')}</span><span class="cell-sub">${esc(x.skills||x.experience||'')}</span></td><td><span class="cell-title">${esc(x.event_title||'Any event')}</span><span class="cell-sub">${esc(x.member_status||'')}</span></td><td><span class="cell-title">${esc(x.state_chapter||'No state')}</span><span class="cell-sub">${esc([x.lga,x.ward].filter(Boolean).join(' • '))}</span></td><td>${esc(x.availability||'')}</td><td>${statusBadge(x.status)}</td><td>${esc((x.created_at||'').slice(0,10))}</td><td><div class="action-group"><button class="icon-btn" data-view-record="volunteers:${esc(x.id)}"><i class="fa-solid fa-eye"></i>View</button><button class="icon-btn green" data-action="volunteers:${esc(x.id)}:approved">Approve</button><button class="icon-btn gold" data-action="volunteers:${esc(x.id)}:assigned">Assign</button><button class="icon-btn" data-action="volunteers:${esc(x.id)}:checked_in">Check In</button><button class="icon-btn red" data-action="volunteers:${esc(x.id)}:rejected">Reject</button></div></td></tr>`).join('');}
    if(kind==='rsvps'){headers=['Attendee','Event','Guests','Chapter','Attendance Note','Status','Submitted','Actions'];sub='Premium RSVP and attendance report for confirmation and check-in.';body=rows.map(x=>`<tr><td><span class="cell-title">${esc(x.full_name||'Unnamed attendee')}</span><span class="cell-sub">${esc(x.phone||'No phone')} ${x.email?'• '+esc(x.email):''}</span></td><td><span class="cell-title">${esc(x.event_title||'No event selected')}</span><span class="cell-sub">${esc(x.member_status||'')}</span></td><td class="amount-cell">${esc(x.guest_count||'1')}</td><td>${esc(x.state_chapter||'')}</td><td><span class="cell-sub">${esc(x.attendance_note||'')}</span></td><td>${statusBadge(x.status)}</td><td>${esc((x.created_at||'').slice(0,10))}</td><td><div class="action-group"><button class="icon-btn" data-view-record="rsvps:${esc(x.id)}"><i class="fa-solid fa-eye"></i>View</button><button class="icon-btn green" data-action="rsvps:${esc(x.id)}:confirmed">Confirm</button><button class="icon-btn gold" data-action="rsvps:${esc(x.id)}:checked_in">Check In</button><button class="icon-btn red" data-action="rsvps:${esc(x.id)}:cancelled">Cancel</button></div></td></tr>`).join('');}
    if(kind==='events'){headers=['Event','Date / Time','Location','Targets','Capacity','Status','Created','Actions'];sub='Published events appear on sponsor, volunteer and RSVP public pages.';body=rows.map(x=>`<tr><td><span class="cell-title">${esc(x.title||'Untitled event')}</span><span class="cell-sub">${esc(x.event_type||'')}</span></td><td><span class="cell-title">${esc(x.event_date||'No date')}</span><span class="cell-sub">${esc([x.start_time,x.end_time].filter(Boolean).join(' - '))}</span></td><td>${esc(x.location||'')}</td><td><span class="amount-cell">${money(x.sponsorship_target)}</span></td><td><span class="cell-title">Vol: ${esc(x.volunteer_slots_required||0)}</span><span class="cell-sub">RSVP: ${esc(x.rsvp_capacity||0)}</span></td><td>${statusBadge(x.status)}</td><td>${esc((x.created_at||'').slice(0,10))}</td><td><div class="action-group"><button class="icon-btn" data-view-record="events:${esc(x.id)}">View</button><button class="icon-btn green" data-action="events:${esc(x.id)}:published">Publish</button><button class="icon-btn gold" data-action="events:${esc(x.id)}:closed">Close</button><button class="icon-btn red" data-action="events:${esc(x.id)}:archived">Archive</button></div></td></tr>`).join('');}
    if(kind==='verification'){headers=['Payment Ref','Source','Name','Amount','Sender / Txn','Status','Submitted','Actions'];sub='Unified pending payment queue for donation and sponsorship transfer verification.';body=rows.map(x=>{const real=x._kind||'donations';return `<tr><td><span class="cell-ref"><i class="fa-solid fa-money-check"></i>${esc(x.payment_ref||'No payment ref')}</span><span class="cell-sub">${esc(x.donation_ref||x.sponsorship_ref||'')}</span></td><td>${esc(real==='sponsorships'?'Sponsorship':'Donation')}</td><td><span class="cell-title">${esc(x.donor_name||x.sponsor_name||'Unnamed')}</span><span class="cell-sub">${esc(x.phone||'')}</span></td><td class="amount-cell">${money(x.amount)}</td><td><span class="cell-title">${esc(x.transfer_sender_name||'No sender')}</span><span class="cell-sub">${esc(x.bank_transaction_ref||'No bank ref')}</span></td><td>${statusBadge(x.status)}</td><td>${esc((x.created_at||'').slice(0,10))}</td><td>${rowActions(real,x.id,x.status)}</td></tr>`}).join('');}
    if(kind==='receipts'){headers=['Receipt Ref','Recipient','Source','Amount','Status','Date','Actions'];sub='Saved receipts can be viewed and downloaded only as PDF.';body=rows.map(x=>{const ref=`receipts:${esc(x.id)}`;return `<tr><td><button type="button" class="receipt-ref-button" data-view-receipt="${ref}" title="Open full receipt PDF"><span class="cell-ref"><i class="fa-solid fa-receipt"></i>${esc(x.receipt_ref||'No receipt ref')}</span></button><span class="cell-sub">${esc(x.payment_ref||'')}</span></td><td><span class="cell-title">${esc(x.recipient_name||'No recipient')}</span><span class="cell-sub">${esc(x.recipient_phone||x.phone||'')}</span></td><td>${esc(x.source_type||'')}</td><td class="amount-cell">${money(x.amount)}</td><td>${statusBadge(x.receipt_status||x.status)}</td><td>${esc((x.created_at||'').slice(0,10))}</td><td><div class="action-group"><button class="icon-btn" data-view-record="${ref}"><i class="fa-solid fa-eye"></i>Details</button><button class="icon-btn gold" data-preview-receipt="${ref}"><i class="fa-solid fa-eye"></i>Preview</button><button class="icon-btn" data-view-receipt="${ref}"><i class="fa-solid fa-file-pdf"></i>View PDF</button><button class="icon-btn green" data-download-receipt="${ref}"><i class="fa-solid fa-download"></i>Download PDF</button></div></td></tr>`}).join('');}
    return reportShell(kind,rows,headers,body,sub);}
  function renderAdminTables(){const data=state.admin.data;const map={donations:data.donations||[],pledges:(data.donations||[]).filter(x=>String(x.donation_type||'').match(/item|material|vehicle|office|fuel|sound|canop|media|printing/i)),sponsorships:data.sponsorships||[],volunteers:data.volunteers||[],rsvps:data.rsvps||[],events:data.events||[],verification:[...(data.donations||[]).map(x=>({...x,_kind:'donations'})),...(data.sponsorships||[]).map(x=>({...x,_kind:'sponsorships'}))].filter(x=>['pending_verification','awaiting_transfer','unmatched'].includes(x.status)),receipts:data.receipts||[]};Object.entries(map).forEach(([key,rows])=>{const box=$(`#${key}Table`);if(box){box.innerHTML=tableHTML(rows,key);}});bindAdminTableActions();}
  function bindAdminTableActions(){
    $$('[data-action]').forEach(btn=>btn.onclick=()=>{const [kind,id,status]=btn.dataset.action.split(':');updateStatus(kind,id,status);});
    $$('[data-view-record]').forEach(btn=>btn.onclick=()=>showRecord(btn.dataset.viewRecord));
    $$('[data-receipt]').forEach(btn=>btn.onclick=()=>generateReceipt(btn.dataset.receipt));
    $$('[data-fill-receipt],[data-preview-receipt]').forEach(btn=>btn.onclick=()=>previewReceipt(btn.dataset.fillReceipt||btn.dataset.previewReceipt));
    $$('[data-view-receipt]').forEach(btn=>btn.onclick=()=>viewReceiptPdf(btn.dataset.viewReceipt));
    $$('[data-download-receipt]').forEach(btn=>btn.onclick=()=>downloadReceiptPdf(btn.dataset.downloadReceipt));
    $$('[data-report-search]').forEach(input=>input.oninput=filterPremiumReport);
  }
  function filterPremiumReport(event){const input=event.currentTarget;const shell=input.closest('[data-report]');const q=String(input.value||'').toLowerCase().trim();shell?.querySelectorAll('tbody tr').forEach(row=>{row.style.display=!q||row.textContent.toLowerCase().includes(q)?'':'none';});}
  async function updateStatus(kind,id,status){const c=await waitClient();const table={donations:'apsg_donations',sponsorships:'apsg_sponsorships',volunteers:'apsg_volunteers',rsvps:'apsg_rsvps',events:'apsg_events'}[kind];if(!table)return;try{const patch={status,updated_at:new Date().toISOString()};if(['confirmed','rejected','unmatched'].includes(status))patch.payment_status=status;const {error}=await c.from(table).update(patch).eq('id',id);if(error)throw error;toast('Status updated');await loadAdminData();}catch(e){toast(e.message||'Status update failed','error');}}
  function findRecord(ref){const [kind,id]=ref.split(':');const key=kind;const arr=state.admin.data[key]||[];return {kind,record:arr.find(x=>String(x.id)===String(id))};}
  function drawerField(label,value,full=false){return `<div class="drawer-field-card ${full?'full':''}"><span>${esc(label)}</span><strong>${esc(value||'—')}</strong></div>`;}
  function detailPairs(kind,record){if(kind==='donations')return [['Donation Ref',record.donation_ref],['Payment Ref',record.payment_ref],['Receipt Ref',record.receipt_ref],['Donor',record.donor_name],['Phone',record.phone],['Email',record.email],['Donation Type',record.donation_type],['Impact Area',record.impact_area],['Item Category',record.item_category],['Amount',money(record.amount)],['Status',record.status],['Recognition',record.recognition_preference],['State',record.state_chapter],['LGA',record.lga],['Ward',record.ward],['Transfer Sender',record.transfer_sender_name],['Bank Transaction Ref',record.bank_transaction_ref],['Note',record.donation_note||record.payment_note,true]];
    if(kind==='sponsorships')return [['Sponsorship Ref',record.sponsorship_ref],['Payment Ref',record.payment_ref],['Receipt Ref',record.receipt_ref],['Sponsor',record.sponsor_name],['Organization',record.organization_name],['Phone',record.phone],['Email',record.email],['Event',record.event_title],['Package',record.package_name],['Amount',money(record.amount)],['Status',record.status],['Recognition',record.recognition_preference],['Transfer Sender',record.transfer_sender_name],['Bank Transaction Ref',record.bank_transaction_ref],['Note',record.sponsor_note||record.payment_note,true]];
    if(kind==='volunteers')return [['Full Name',record.full_name],['Phone',record.phone],['Email',record.email],['Member Status',record.member_status],['Membership ID',record.membership_id],['State',record.state_chapter],['LGA',record.lga],['Ward',record.ward],['Category',record.category],['Event',record.event_title],['Availability',record.availability],['Status',record.status],['Skills',record.skills,true],['Experience',record.experience,true],['Notes',record.notes,true],['Emergency Contact',`${record.emergency_contact_name||''} ${record.emergency_contact_phone||''}`]];
    if(kind==='rsvps')return [['Full Name',record.full_name],['Phone',record.phone],['Email',record.email],['Member Status',record.member_status],['State Chapter',record.state_chapter],['Event',record.event_title],['Guest Count',record.guest_count||1],['Status',record.status],['Attendance Note',record.attendance_note,true]];
    if(kind==='events')return [['Title',record.title],['Event Type',record.event_type],['Date',record.event_date],['Start Time',record.start_time],['End Time',record.end_time],['Location',record.location],['Sponsorship Target',money(record.sponsorship_target)],['Volunteer Slots',record.volunteer_slots_required],['RSVP Capacity',record.rsvp_capacity],['Status',record.status],['Description',record.description,true]];
    if(kind==='receipts')return [['Receipt Ref',record.receipt_ref],['Payment Ref',record.payment_ref],['Source Type',record.source_type],['Recipient',record.recipient_name],['Amount',money(record.amount)],['Status',record.receipt_status||record.status],['Phone',record.recipient_phone||record.phone],['Email',record.recipient_email||record.email],['Source Ref',record.source_ref],['Supporter Ref',record.supporter_ref],['Note',record.receipt_note,true]];
    return Object.entries(record).map(([k,v])=>[titleCaseText(k),typeof v==='object'?JSON.stringify(v):v]);}
  function showRecord(ref){const {kind,record}=findRecord(ref);if(!record)return;$('#drawerBackdrop')?.classList.remove('hidden');const dr=$('#recordDrawer');if(!dr)return;const pairs=detailPairs(kind,record);const canReceipt=['donations','sponsorships','receipts'].includes(kind);dr.classList.add('show');dr.innerHTML=`<div class="section-head"><div><p class="section-kicker">Premium Record Report</p><h3 class="section-title" style="font-size:1.5rem">${esc(reportLabel(kind))}</h3><p class="section-copy">Structured administrative view. No raw JSON output.</p></div><button class="icon-btn" onclick="APSGInvolveAdmin.closeDrawer()"><i class="fa-solid fa-xmark"></i>Close</button></div>${canReceipt?`<div class="drawer-actions"><button class="premium-btn gold" data-preview-receipt="${esc(ref)}"><i class="fa-solid fa-eye"></i>Preview</button><button class="premium-btn ghost" data-view-receipt="${esc(ref)}"><i class="fa-solid fa-file-pdf"></i>View Receipt PDF</button><button class="premium-btn green" data-download-receipt="${esc(ref)}"><i class="fa-solid fa-download"></i>Download Receipt PDF</button></div>`:''}<div class="premium-drawer-grid">${pairs.map(([label,value,full])=>drawerField(label,value,Boolean(full))).join('')}</div>`;bindAdminTableActions();}
  function receiptModeLabel(mode){return {pending_payment:'Pending Payment Confirmation',final_donation:'Final Donation Receipt',sponsorship:'Sponsorship Receipt',item_pledge:'Item Pledge Acknowledgement'}[mode]||'Support Receipt';}
  function receiptStatusLabel(status){return {pending:'Pending',final:'Final',cancelled:'Cancelled'}[status]||titleCaseText(status||'pending');}
  function titleCaseText(v){return String(v||'').replace(/[_-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
  function receiptDate(){return new Date().toLocaleDateString('en-NG',{year:'numeric',month:'long',day:'numeric'});}
  function receiptForm(){return $('#receiptStudioForm');}
  function getReceiptData(){const form=receiptForm();const fd=form?new FormData(form):new FormData();const refs=fallbackRefs(String(fd.get('source_type')||'donation').includes('sponsor')?'sponsor':'donation');return {receipt_mode:String(fd.get('receipt_mode')||'pending_payment'),receipt_status:String(fd.get('receipt_status')||'pending'),source_type:String(fd.get('source_type')||'donation'),recipient_name:String(fd.get('recipient_name')||'APSG Supporter'),phone:String(fd.get('phone')||''),email:String(fd.get('email')||''),state_chapter:String(fd.get('state_chapter')||''),support_category:String(fd.get('support_category')||'APSG General Support'),amount:String(fd.get('amount')||'0'),source_ref:String(fd.get('source_ref')||refs.donation_ref||refs.sponsorship_ref||''),payment_ref:String(fd.get('payment_ref')||refs.payment_ref||''),receipt_ref:String(fd.get('receipt_ref')||refs.receipt_ref||''),supporter_ref:String(fd.get('supporter_ref')||refs.donor_ref||''),transfer_sender_name:String(fd.get('transfer_sender_name')||''),receipt_note:String(fd.get('receipt_note')||'This is a pending payment confirmation receipt. Final receipt will be issued after APSG confirms the bank transfer.')};}
  function setReceiptField(name,value){const field=receiptForm()?.elements?.[name];if(field)field.value=value??'';}
  function updateReceiptPreview(){const r=getReceiptData();const statusEl=$('#receiptPreviewStatus');if(statusEl){statusEl.textContent=receiptStatusLabel(r.receipt_status);statusEl.className=`receipt-status ${r.receipt_status==='final'?'final':r.receipt_status==='cancelled'?'cancelled':'pending'}`;}setTextById('receiptPreviewRef',r.receipt_ref||'—');setTextById('receiptPreviewDate',receiptDate());setTextById('receiptPreviewName',r.recipient_name||'—');setTextById('receiptPreviewType',receiptModeLabel(r.receipt_mode));setTextById('receiptPreviewAmount',money(r.amount));setTextById('receiptPreviewCategory',r.support_category||'—');setTextById('receiptPreviewSourceRef',r.source_ref||'—');setTextById('receiptPreviewPaymentRef',r.payment_ref||'—');setTextById('receiptPreviewSupporterRef',r.supporter_ref||'—');setTextById('receiptPreviewState',r.state_chapter||'—');setTextById('receiptPreviewNote',r.receipt_note||'—');setTextById('receiptPreviewVerify',r.receipt_ref||r.payment_ref||'APSG-RCP');return r;}
  function setTextById(id,value){const el=$('#'+id);if(el)el.textContent=value;}
  function resetReceiptStudio(){const form=receiptForm();if(form)form.reset();const refs=fallbackRefs('donation');setReceiptField('receipt_ref',refs.receipt_ref);setReceiptField('payment_ref',refs.payment_ref);setReceiptField('source_ref',refs.donation_ref);setReceiptField('supporter_ref',refs.donor_ref);updateReceiptPreview();toast('Receipt studio reset');}
  function fillReceiptStudio(ref){const {kind,record}=findRecord(ref);if(!record)return toast('Record not found','error');const isSponsor=kind==='sponsorships'||record.source_type==='sponsorship';const isReceipt=kind==='receipts';const sourceType=isReceipt?record.source_type:(isSponsor?'sponsorship':'donation');const status=record.receipt_status||((record.status==='confirmed'||record.payment_status==='confirmed')?'final':'pending');setReceiptField('source_type',sourceType||'donation');setReceiptField('receipt_mode',sourceType==='sponsorship'?'sponsorship':sourceType==='item_pledge'?'item_pledge':status==='final'?'final_donation':'pending_payment');setReceiptField('receipt_status',status==='final'?'final':status==='cancelled'?'cancelled':'pending');setReceiptField('recipient_name',record.recipient_name||record.donor_name||record.sponsor_name||record.full_name||'APSG Supporter');setReceiptField('phone',record.phone||'');setReceiptField('email',record.email||'');setReceiptField('state_chapter',record.state_chapter||record.state||'');setReceiptField('support_category',record.support_category||record.impact_area||record.package_name||record.event_title||'APSG General Support');setReceiptField('amount',record.amount||0);setReceiptField('source_ref',record.donation_ref||record.sponsorship_ref||record.source_ref||'');setReceiptField('payment_ref',record.payment_ref||'');setReceiptField('receipt_ref',record.receipt_ref||fallbackRefs(isSponsor?'sponsor':'donation').receipt_ref);setReceiptField('supporter_ref',record.donor_ref||record.supporter_ref||'');setReceiptField('transfer_sender_name',record.transfer_sender_name||'');setReceiptField('receipt_note',record.receipt_note||((status==='final')?'This is the final APSG support receipt issued after payment verification.':'This is a pending payment confirmation receipt. Final receipt will be issued after APSG confirms the bank transfer.'));updateReceiptPreview();activateAdminTab('receipts');toast('Receipt preview loaded');}

  function previewReceipt(ref){
    if(ref)fillReceiptStudio(ref);
    updateReceiptPreview();
    activateAdminTab('receipts');
    const preview=$('#receiptPreview');
    if(preview){preview.scrollIntoView({behavior:'smooth',block:'center'});preview.classList.add('receipt-preview-pulse');setTimeout(()=>preview.classList.remove('receipt-preview-pulse'),900);}
    toast('Receipt preview ready');
  }
  function receiptPayloadForView(ref){
    if(ref)fillReceiptStudio(ref);
    const r=updateReceiptPreview();
    try{
      sessionStorage.setItem('apsg_receipt_view_payload',JSON.stringify(r));
      if(r.receipt_ref)sessionStorage.setItem('apsg_receipt_payload_'+r.receipt_ref,JSON.stringify(r));
    }catch(e){}
    return r;
  }
  function viewPdfUrl(r){
    const params=new URLSearchParams();
    if(r?.receipt_ref)params.set('ref',r.receipt_ref);
    if(r?.payment_ref)params.set('payment',r.payment_ref);
    params.set('from','admin-get-involved');
    return '/admin/viewpdf.html?'+params.toString();
  }

  function pdfSafe(v){return String(v==null?'':v).replace(/\s+/g,' ').trim();}
  function pdfName(r){return `${(r.receipt_ref||'apsg-receipt').replace(/[^a-z0-9-]+/gi,'-')}.pdf`;}
  const APSG_LOGO_URLS=['/assets/images/logo/apsg.png','/assets/images/logo/apsg1.png','/assets/images/apsg.png'];
  let apsgLogoDataUrlPromise=null;
  function blobToDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});}
  async function loadApsgLogoDataUrl(){
    if(apsgLogoDataUrlPromise)return apsgLogoDataUrlPromise;
    apsgLogoDataUrlPromise=(async()=>{
      for(const url of APSG_LOGO_URLS){
        try{const res=await fetch(url,{cache:'force-cache'});if(!res.ok)continue;const blob=await res.blob();if(!String(blob.type||'').startsWith('image/'))continue;return await blobToDataUrl(blob);}catch(e){}
      }
      return '';
    })();
    return apsgLogoDataUrlPromise;
  }
  function imageFormatFromDataUrl(dataUrl){return /^data:image\/jpe?g/i.test(String(dataUrl||''))?'JPEG':'PNG';}
  function drawLogoOrFallback(doc,dataUrl,x,y,size){
    try{if(dataUrl){doc.addImage(dataUrl,imageFormatFromDataUrl(dataUrl),x,y,size,size);return true;}}catch(e){}
    doc.setFillColor(255,255,255);doc.roundedRect(x,y,size,size,12,12,'F');doc.setTextColor(5,53,31);doc.setFont('helvetica','bold');doc.setFontSize(14);doc.text('APSG',x+8,y+(size/2)+5);return false;
  }

  async function pdfDocForReceipt(r){
    const PDF=window.jspdf?.jsPDF||window.jsPDF;
    if(!PDF){toast('PDF engine is still loading. Please try again.','error');return null;}
    const logoDataUrl=await loadApsgLogoDataUrl();
    const doc=new PDF({orientation:'portrait',unit:'pt',format:'a4'});
    const w=doc.internal.pageSize.getWidth(),h=doc.internal.pageSize.getHeight();
    const deep=[5,53,31],green=[15,122,61],emerald=[15,118,110],gold=[216,173,52],muted=[100,116,105],cream=[255,250,240],line=[218,224,218];
    const status=receiptStatusLabel(r.receipt_status);
    const mode=receiptModeLabel(r.receipt_mode);
    const statusText=(r.receipt_status==='final'||r.receipt_status==='confirmed')?'FINAL':(r.receipt_status==='cancelled'||r.receipt_status==='rejected')?'VOID':'PENDING';

    // Header band
    doc.setFillColor(...deep);doc.rect(0,0,w,126,'F');
    doc.setFillColor(...green);doc.triangle(w,0,w,126,w-215,0,'F');
    doc.setFillColor(...gold);doc.rect(0,122,w,4,'F');
    drawLogoOrFallback(doc,logoDataUrl,42,29,58);
    doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(18);doc.text('APC Progressive Support Group',116,48);
    doc.setFontSize(8);doc.setTextColor(236,244,238);doc.text('OFFICIAL APSG GET INVOLVED SUPPORT RECEIPT',116,66);
    doc.setFont('helvetica','normal');doc.setFontSize(8);doc.text(`Issued: ${receiptDate()}`,116,82);
    doc.setDrawColor(...gold);doc.setLineWidth(.8);doc.line(116,92,330,92);
    doc.setFillColor(255,255,255);doc.roundedRect(w-178,36,136,32,16,16,'F');
    doc.setTextColor(...deep);doc.setFont('helvetica','bold');doc.setFontSize(9);doc.text(status.toUpperCase(),w-160,56);

    // Watermark
    doc.setTextColor(236,240,236);doc.setFont('helvetica','bold');doc.setFontSize(64);
    doc.text(statusText,w/2,287,{align:'center',angle:-22});
    if(logoDataUrl){try{doc.addImage(logoDataUrl,imageFormatFromDataUrl(logoDataUrl),w/2-45,220,90,90);}catch(e){}}

    // Title
    doc.setTextColor(...deep);doc.setFont('helvetica','bold');doc.setFontSize(30);doc.text(mode,42,166,{maxWidth:w-84});
    doc.setFont('helvetica','normal');doc.setFontSize(9);doc.setTextColor(...muted);doc.text('Generated by APSG Get Involved Command Center for finance/admin verification and official record keeping.',42,184,{maxWidth:w-84});
    doc.setDrawColor(230,235,230);doc.line(42,202,w-42,202);

    function box(x,y,bw,bh,label,value){
      doc.setDrawColor(...line);doc.setFillColor(...cream);doc.roundedRect(x,y,bw,bh,10,10,'FD');
      doc.setFont('helvetica','bold');doc.setFontSize(7);doc.setTextColor(112,128,120);doc.text(String(label).toUpperCase(),x+12,y+18);
      doc.setFontSize(10);doc.setTextColor(...deep);doc.text(pdfSafe(value)||'—',x+12,y+39,{maxWidth:bw-24});
    }
    box(42,222,246,62,'Receipt Reference',r.receipt_ref);
    box(306,222,246,62,'Payment Reference',r.payment_ref);
    box(42,296,246,62,'Source Reference',r.source_ref);
    box(306,296,246,62,'Donor / Sponsor Reference',r.supporter_ref);
    box(42,370,246,62,'Received From',r.recipient_name);
    box(306,370,246,62,'Phone / Email',[r.phone,r.email].filter(Boolean).join(' • '));
    box(42,444,246,62,'Support Type',mode);
    box(306,444,246,62,'Support Category',r.support_category);

    doc.setFillColor(255,250,240);doc.setDrawColor(...gold);doc.roundedRect(42,526,w-84,78,14,14,'FD');
    doc.setTextColor(126,86,16);doc.setFont('helvetica','bold');doc.setFontSize(8);doc.text('AMOUNT / DECLARED SUPPORT VALUE',58,552);
    doc.setTextColor(...deep);doc.setFontSize(27);doc.text(money(r.amount),58,580,{maxWidth:w-245});
    doc.setFillColor(...deep);doc.roundedRect(w-190,552,132,27,13,13,'F');
    doc.setTextColor(255,255,255);doc.setFontSize(8);doc.text((r.source_type||'support').toUpperCase(),w-174,569);

    box(42,626,246,62,'State / Chapter',r.state_chapter);
    box(306,626,246,62,'Transfer Sender',r.transfer_sender_name);
    doc.setFillColor(255,255,255);doc.setDrawColor(...line);doc.roundedRect(42,704,w-84,70,10,10,'FD');
    doc.setTextColor(112,128,120);doc.setFont('helvetica','bold');doc.setFontSize(7);doc.text('OFFICIAL RECEIPT NOTE',58,724);
    doc.setTextColor(...deep);doc.setFontSize(10);doc.text(pdfSafe(r.receipt_note),58,746,{maxWidth:w-116});

    doc.setDrawColor(210,218,210);doc.line(42,h-82,w-42,h-82);
    doc.setFont('helvetica','normal');doc.setFontSize(8);doc.setTextColor(...muted);doc.text('This receipt is valid only when the reference exists in APSG administrative records. Manual bank transfer verification remains required unless a payment gateway is later integrated.',42,h-61,{maxWidth:w-180});
    doc.setFont('helvetica','bold');doc.setTextColor(...deep);doc.text('APSG Authorized Finance Desk',w-196,h-45);
    doc.setDrawColor(...deep);doc.line(w-222,h-60,w-42,h-60);
    return doc;
  }
  async function viewReceiptPdf(ref){const r=receiptPayloadForView(ref);window.open(viewPdfUrl(r),'_blank','noopener');toast('Opening full receipt PDF viewer');}
  function closeReceiptPdfViewer(){const modal=$('#receiptPdfModal'),frame=$('#receiptPdfFrame');const previous=modal?.dataset?.pdfUrl;if(previous)URL.revokeObjectURL(previous);if(frame){frame.removeAttribute('src');}modal?.classList.remove('show');if(modal)delete modal.dataset.pdfUrl;}
  async function downloadReceiptPdf(ref){if(ref)fillReceiptStudio(ref);const r=updateReceiptPreview();const doc=await pdfDocForReceipt(r);if(!doc)return;doc.save(pdfName(r));toast('Receipt PDF downloaded');}
  function openWhatsAppReceipt(){const r=updateReceiptPreview();const phone=(state.settings.contact?.whatsapp||CONTACT_FALLBACK.whatsapp);const msg=[`APSG Receipt Summary`, `Receipt Ref: ${r.receipt_ref}`, `Status: ${receiptStatusLabel(r.receipt_status)}`, `Name: ${r.recipient_name}`, `Type: ${receiptModeLabel(r.receipt_mode)}`, `Amount/Value: ${money(r.amount)}`, `Payment Ref: ${r.payment_ref||'N/A'}`, `PDF: Please download from APSG admin receipt studio.`, `Note: ${r.receipt_note}`].join('\n');window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener');}
  async function saveManualReceipt(){const c=await waitClient();if(!c)return toast('Supabase not connected','error');const r=updateReceiptPreview();const payload={receipt_ref:r.receipt_ref,source_type:r.source_type,source_id:null,payment_ref:r.payment_ref,recipient_name:r.recipient_name,amount:num(r.amount),receipt_status:r.receipt_status,receipt_note:r.receipt_note};try{const {error}=await c.from('apsg_payment_receipts').insert(payload);if(error)throw error;toast('Receipt saved to register');await loadAdminData();}catch(e){toast(e.message||'Could not save receipt','error');}}
  async function generateReceipt(ref){const {kind,record}=findRecord(ref);if(!record)return;const c=await waitClient();const isSponsor=kind==='sponsorships';const refs=fallbackRefs(isSponsor?'sponsor':'donation');const payload={source_type:isSponsor?'sponsorship':'donation',source_id:record.id,receipt_ref:record.receipt_ref||refs.receipt_ref,payment_ref:record.payment_ref||refs.payment_ref,recipient_name:record.donor_name||record.sponsor_name||record.full_name,recipient_phone:record.phone||'',recipient_email:record.email||'',amount:record.amount||0,receipt_status:record.status==='confirmed'?'final':'pending',receipt_note:record.status==='confirmed'?'This is the final APSG support receipt issued after payment verification.':'This is a pending payment confirmation receipt. Final receipt will be issued after APSG confirms the bank transfer.',source_ref:record.donation_ref||record.sponsorship_ref||'',supporter_ref:record.donor_ref||''};try{if(c){const {error}=await c.from('apsg_payment_receipts').insert(payload);if(error)throw error;}toast('Receipt record generated');await loadAdminData();const latest=(state.admin.data.receipts||[]).find(x=>x.receipt_ref===payload.receipt_ref);fillReceiptStudio(latest?`receipts:${latest.id}`:ref);await viewReceiptPdf();}catch(e){toast(e.message||'Could not generate receipt','error');}}
function closeDrawer(){$('#drawerBackdrop')?.classList.add('hidden');$('#recordDrawer')?.classList.remove('show');}
  function exportCsv(key){const rows=(state.admin.data[key]||[]);if(!rows.length)return toast('No records to export','error');const cols=Object.keys(rows[0]);const csv=[cols.join(',')].concat(rows.map(r=>cols.map(c=>`"${String(r[c]??'').replace(/"/g,'""')}"`).join(','))).join('\n');const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`apsg-${key}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);}
  async function saveEvent(form){const c=await waitClient();const fd=new FormData(form);const row={title:fd.get('title'),event_type:fd.get('event_type'),description:fd.get('description'),event_date:fd.get('event_date'),start_time:fd.get('start_time'),end_time:fd.get('end_time'),location:fd.get('location'),image_url:fd.get('image_url'),sponsorship_target:num(fd.get('sponsorship_target')),volunteer_slots_required:num(fd.get('volunteer_slots_required')),rsvp_capacity:num(fd.get('rsvp_capacity')),status:fd.get('status')||'draft'};try{const {error}=await c.from('apsg_events').insert(row);if(error)throw error;toast('Event saved');form.reset();await loadAdminData();}catch(e){toast(e.message||'Could not save event','error');}}
  async function saveSettings(form){const c=await waitClient();const fd=new FormData(form);const entries=[
    {key:'account_name',value:fd.get('account_name'),category:'finance',public_visible:true,description:'APSG finance account name'},
    {key:'bank_name',value:fd.get('bank_name'),category:'finance',public_visible:true,description:'APSG receiving bank name'},
    {key:'account_number',value:fd.get('account_number'),category:'finance',public_visible:true,description:'APSG receiving account number'},
    {key:'minimum_donation',value:num(fd.get('minimum_donation')),category:'finance',public_visible:true,description:'Minimum donation amount'},
    {key:'finance_email',value:fd.get('finance_email'),category:'finance',public_visible:false,description:'Finance desk email'},
    {key:'whatsapp',value:fd.get('whatsapp'),category:'organization',public_visible:true,description:'Public WhatsApp number for support receipts'},
    {key:'donation_bundles',value:String(fd.get('donation_bundles')||'').split(',').map(num).filter(Boolean),category:'finance',public_visible:true,description:'Donation quick amount bundles'},
    {key:'sponsorship_bundles',value:String(fd.get('sponsorship_bundles')||'').split(',').map(num).filter(Boolean),category:'finance',public_visible:true,description:'Sponsorship quick amount bundles'}
  ];try{if(window.APSGSettings){await window.APSGSettings.saveSettings(entries);}
    else{if(!c)throw new Error('Supabase not connected');const rows=entries.map(x=>({setting_key:x.key,setting_value:x.value,category:x.category,public_visible:x.public_visible,description:x.description,updated_at:new Date().toISOString()}));const {error}=await c.from('apsg_settings').upsert(rows,{onConflict:'setting_key'});if(error)throw error;}await loadSettings();toast('Settings saved to centralized APSG settings.');}catch(e){toast(e.message||'Could not save settings','error');}}
  function activateAdminTab(tab){$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('.admin-panel').forEach(p=>p.classList.toggle('active',p.id===`tab-${tab}`));window.toggleAdminSidebar?.(false);}function initAdmin(){if(!$('[data-admin-get-involved]'))return;checkAdmin().then(()=>loadAdminData()).then(()=>{resetReceiptStudio();});$$('[data-tab]').forEach(btn=>btn.addEventListener('click',()=>activateAdminTab(btn.dataset.tab)));$$('[data-tab-jump]').forEach(btn=>btn.addEventListener('click',()=>activateAdminTab(btn.dataset.tabJump)));$('#adminEventForm')?.addEventListener('submit',e=>{e.preventDefault();saveEvent(e.currentTarget);});$('#adminSettingsForm')?.addEventListener('submit',e=>{e.preventDefault();saveSettings(e.currentTarget);});$('#receiptStudioForm')?.addEventListener('input',()=>updateReceiptPreview());$$('[data-export]').forEach(b=>b.addEventListener('click',()=>exportCsv(b.dataset.export)));$('#drawerBackdrop')?.addEventListener('click',closeDrawer);window.APSGInvolveAdmin={closeDrawer,loadAdminData,exportCsv,activateAdminTab,fillReceiptStudio,previewReceipt,updateReceiptPreview,resetReceiptStudio,saveManualReceipt,viewReceiptPdf,downloadReceiptPdf,closeReceiptPdfViewer,openWhatsAppReceipt};}
  function sidebar(){window.toggleAdminSidebar=function(show){const s=$('#adminSidebar'),o=$('#mobileOverlay');if(!s||!o)return;s.classList.toggle('open',show);o.classList.toggle('hidden',!show);};window.logout=async function(){const c=client();if(c?.auth)await c.auth.signOut();location.href='/admin/login.html';};document.addEventListener('keydown',e=>{if(e.key==='Escape'){window.toggleAdminSidebar?.(false);closeDrawer();}});}
  document.addEventListener('DOMContentLoaded',()=>{publicInit();initAdmin();sidebar();});
})();
